ALTER TABLE clinics ADD COLUMN sms_enabled boolean NOT NULL DEFAULT false, ADD COLUMN whatsapp_enabled boolean NOT NULL DEFAULT false, ADD COLUMN sms_sender varchar(30), ADD COLUMN whatsapp_sender varchar(30), ADD COLUMN reminder_channel varchar(20) NOT NULL DEFAULT 'WHATSAPP', ADD COLUMN average_visit_minutes int NOT NULL DEFAULT 12;
ALTER TABLE branches ADD COLUMN second_opens_at time, ADD COLUMN second_closes_at time, ADD COLUMN queue_paused boolean NOT NULL DEFAULT false, ADD COLUMN current_token int NOT NULL DEFAULT 0;
CREATE TABLE queue_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),branch_id uuid NOT NULL REFERENCES branches(id),queue_date date NOT NULL DEFAULT current_date,token_number int NOT NULL,patient_name varchar(160) NOT NULL,mobile varchar(20) NOT NULL,age int CHECK(age BETWEEN 0 AND 130),weight_kg numeric(5,2),bp varchar(20),sugar varchar(30),status varchar(24) NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING','IN_CONSULTATION','COMPLETED','CANCELLED')),registered_by uuid REFERENCES users(id),started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(branch_id,queue_date,token_number),UNIQUE(branch_id,queue_date,mobile));
CREATE TABLE patient_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),queue_entry_id uuid NOT NULL REFERENCES queue_entries(id) ON DELETE CASCADE,file_name varchar(255) NOT NULL,content_type varchar(100) NOT NULL,file_data bytea NOT NULL,uploaded_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE message_outbox(id bigserial PRIMARY KEY,clinic_id uuid NOT NULL REFERENCES clinics(id),queue_entry_id uuid REFERENCES queue_entries(id),channel varchar(20) NOT NULL CHECK(channel IN ('SMS','WHATSAPP')),sender varchar(30),recipient varchar(20) NOT NULL,message_type varchar(40) NOT NULL,body text NOT NULL,status varchar(20) NOT NULL DEFAULT 'QUEUED',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_queue_daily ON queue_entries(clinic_id,branch_id,queue_date,status,token_number);
CREATE INDEX ix_queue_patient ON queue_entries(clinic_id,mobile,created_at DESC);
